import { db } from './database';
import { NotFoundError } from './errors';

export interface Resource {
  id: string;
  createdAt: Date;
  updatedAt: Date;
}

/** CRUD helpers for the `accounts` table. */
export async function getAccount(id: string): Promise<Resource> {
  const record = await db.accounts.findUnique({
    where: { id },
  });
  if (record === null) {
    throw new NotFoundError('account', id);
  }
  return record;
}

export async function listAccounts(limit = 20): Promise<Resource[]> {
  return db.accounts.findMany({
    take: limit,
    orderBy: { createdAt: 'desc' },
  });
}

